// logLevelClass returns a CSS variant suffix for a log level.
func logLevelClass(level string) string {
	switch level {
	case "error", "fatal":
		return "error"
	case "warn", "warning":
		return "warn"
	case "info":
		return "info"
	case "debug":
		return "debug"
	default:
		return "info"
	}
}

